//! 🧪️ Original command fields and typed provenance cross preparing input exactly once.
use super::*;
use semio_framework_job::{OriginalJobFixtureCaller,OriginalJobDecodeOwner,OperationId,Generation,default_now_us};
use semio_framework_value::{RetainedCloneGrant,ToValue};
fn turn<R>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,g:RetainedCloneGrant,run:impl FnOnce(&mut StepContext<'_>)->Result<R,OriginalTurnFailure>)->R{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(g,decoder,run));let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes),"actual original transaction source receipt {p:?}");result.unwrap()}
fn packed<T:ToValue>(value:&T)->Vec<u8>{let mut allow=|_|true;let mut control=semio_framework_value::NativeEncodeControl::new(1<<24,&mut allow);semio_framework_pack_record::intrinsic::encode_body(&value.to_value(),&Default::default(),&mut control).unwrap()}
#[test]fn original_transaction_preparing_source_preserves_wire_allocations_and_cancellation(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();
 for form in law["forms"].as_array().unwrap(){for cut in law["cancelPrefixes"].as_array().unwrap().iter().map(|value|Some(value.as_u64().unwrap()as usize)).chain([None]){
  let owner=form=="owner";let payload=if owner{law["payload"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as u8).collect()}else{Vec::new()};let ops=if owner{Vec::new()}else{law["preparedOperations"].as_array().unwrap().iter().map(|row|row.as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as u8).collect::<Vec<_>>()).collect::<Vec<_>>()};let pointers=if owner{vec![(payload.as_ptr(),payload.len())]}else{ops.iter().map(|v|(v.as_ptr(),v.len())).collect()};let parent_root=ops.as_ptr();let children=vec![ChildEmit{genesis:None,owner:String::new(),slot:"children".into(),child_id:"original-child".into(),ops:vec![vec![8,9]],op_schema:store::SchemaId("s.test.child#edit".into()),labels:Vec::new()}];let origin=store::MutationOrigin::Contributed{plugin_id:"original contributor λ🙂".into(),mutation_id:store::SchemaId("s.test.child#edit".into()),payload_hash:store::PayloadHash([7;32])};let mut command=store::AppCommand::TransactionPrepare{seq:7,txn_id:law["transactionId"].as_str().unwrap().into(),mutation_id:if owner{law["mutationId"].as_str().unwrap().into()}else{String::new()},payload,prepared_ops:ops,origin:packed(&origin),prepared_child_ops:if owner{Vec::new()}else{packed(&children)}};
  let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:1<<24,maximum_release_bytes:1<<24,maximum_depth:4096};let mut caller=OriginalJobFixtureCaller::admit(OperationId(384),Generation(10),RetainedCloneGrant{maximum_items:1<<30,maximum_copy_bytes:1<<30,maximum_capacity_bytes:1<<29,maximum_release_bytes:1<<29,maximum_depth:4096},default_now_us,u64::MAX,1<<30);let mut decoder=OriginalJobDecodeOwner::empty();let mut source=None;
  let d=RetirementDemand{capacity_bytes:size_of::<OriginalTransactionPrepareSource>(),..fixed::<(OriginalTransactionPrepareSource,Fields)>()};for axis in 0..4{let mut denied=g;match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes=d.copy_bytes-1,2=>denied.maximum_capacity_bytes=d.capacity_bytes-1,3=>denied.maximum_depth=0,_=>unreachable!()}turn(&mut caller,&mut decoder,denied,|cx|{assert!(!OriginalTransactionPrepareSource::admit(&mut command,cx,&mut source)?);Ok(())});assert!(source.is_none());let store::AppCommand::TransactionPrepare{txn_id,..}=&command else{unreachable!()};assert_eq!(txn_id,law["transactionId"].as_str().unwrap());}
  turn(&mut caller,&mut decoder,g,|cx|{assert!(OriginalTransactionPrepareSource::admit(&mut command,cx,&mut source)?);Ok(())});let mut foreign=OriginalJobDecodeOwner::empty();turn(&mut caller,&mut foreign,g,|cx|{assert!(source.as_mut().unwrap().advance(Default::default(),cx).is_err());Ok(())});assert!(foreign.terminal_is_empty());
  for index in 0..262144{if cut==Some(index){break}if turn(&mut caller,&mut decoder,g,|cx|source.as_mut().unwrap().advance(Default::default(),cx)){break}assert!(index<262143,"original transaction preparing source stalled");}
  let mut output=None;if cut.is_none(){turn(&mut caller,&mut decoder,g,|cx|{assert!(source.as_mut().unwrap().take(cx,&mut output)?);Ok(())});let parts=output.as_ref().unwrap();assert_eq!(parts.transaction_id,law["transactionId"].as_str().unwrap());assert_eq!(parts.origin,origin);assert_eq!(parts.operations.iter().map(|v|(v.as_ptr(),v.len())).collect::<Vec<_>>(),pointers);if !owner{assert_eq!(parts.operations.as_ptr(),parent_root);assert_eq!(parts.children,children);}else{assert!(parts.children.is_empty());}let actual:Vec<Vec<u8>>=parts.operations.clone();let expected:Vec<Vec<u8>>=if owner{vec![serde_json::from_value(law["payload"].clone()).unwrap()]}else{serde_json::from_value(law["preparedOperations"].clone()).unwrap()};assert_eq!(actual,expected);}else{caller.cancel().cancel_now();}
  for index in 0..262144{if source.as_ref().unwrap().terminal_is_empty(){break}turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|source.as_mut().unwrap().close_step(cx)));assert!(index<262143,"original transaction source cancellation stalled");}turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=OriginalTransactionPrepareSource::release_demands();close_original_retained_step(cx,d,|_|{source.take();Ok(RetainedCloneStep::Complete(receipt(d)))})?;Ok(())}));
  let mut close=RetainedCloneClose::default();for index in 0..262144{if output.is_none()&&close.is_empty(){break}turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=close.next_owner_demands::<OriginalTransactionPrepareParts>(output.is_some(),&None,4096)?;close_original_retained_step(cx,d,|grant|if close.is_empty(){Ok(close.begin_granted(&mut output,grant)?.unwrap_or(RetainedCloneStep::Complete(Default::default())))}else{close.select(4096)?.step(grant)})?;Ok(())}));assert!(index<262143);}while !decoder.terminal_is_empty(){caller.turn(g,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(4096)?;close_original_retained_step(cx,d,|grant|decoder.close_step(grant))?;Ok(())})).unwrap();}caller.retire(g);
 }}
}
